// Compare origin, path and query only; the #fragment never changes the page.
const toPageKey = (href: string, base?: string) => {
  try {
    const url = new URL(href, base);
    return `${url.origin}${url.pathname}${url.search}`;
  } catch {
    return null;
  }
};

export const CurrentPageBadge: React.FC<{
  href: string;
  currentHref: string;
}> = ({ href, currentHref }) => {
  const pageKey = toPageKey(href, window.location.href);
  const currentPageKey = toPageKey(currentHref, window.location.href);

  if (!pageKey || pageKey !== currentPageKey) {
    return null;
  }

  return (
    <Badge
      variant='accent'
      label={
        <FormattedMessage
          id='current_page.you_are_here'
          defaultMessage='You are here'
        />
      }
    />
  );
};
